SELECT * FROM `alarm_detail` INNER JOIN `alarm_audit`
  and alarm_detail.id = alarm_audit.alarm_id
  and alarm_audit.audit_status = '0';

SELECT count(*) FROM `alarm_detail` INNER JOIN `alarm_audit`
where alarm_detail.alarm_level = '4'
  and alarm_detail.camera_id = #{cameraName}
  and alarm_detail.id = alarm_audit.alarm_id
  and alarm_audit.audit_status = '0';

SELECT count(*) FROM `alarm_detail` INNER JOIN `alarm_audit`
where alarm_detail.camera_id = #{cameraName}
    and alarm_detail.id = alarm_audit.alarm_id
  and alarm_audit.audit_status = '0';

SELECT count(*) FROM `alarm_detail` INNER JOIN `alarm_audit`
where alarm_detail.alarm_area = #{alarmArea}
  and alarm_detail.id = alarm_audit.alarm_id
  and alarm_audit.audit_status = '0';

SELECT count(*) FROM `alarm_detail` INNER JOIN `alarm_audit` INNER JOIN `camera_manager`
where camera_manager.camera_ownership = #{alarmDevice}
  and camera_manager.id = alarm_detail.camera_id
  and alarm_detail.id = alarm_audit.alarm_id
  and alarm_audit.audit_status = '0';

SELECT alarm_detail.*, ky_category.id AS categoryId, alarm_audit.id AS auditId, alarm_audit.audit_people, alarm_audit.audit_reason, alarm_audit.audit_status, alarm_audit.audit_result, alarm_audit.audit_time FROM alarm_detail
LEFT JOIN alarm_audit ON alarm_audit.alarm_id = alarm_detail.id LEFT JOIN ky_category ON ky_category.code = alarm_detail.alarm_type
alarm_detail.alarm_type != #{alarmSearchVo.alarmType}
