#{cameraName}
AND ky_category.id IN
#{category}
AND alarm_detail.alarm_time BETWEEN #{alarmSearchVo.startTime} AND #{alarmSearchVo.endTime}
AND alarm_detail.alarm_level = #{alarmSearchVo.alarmLevel}
AND alarm_audit.audit_status = #{alarmSearchVo.auditStatus}
