SELECT
COUNT(*) AS allCount,
SUM(CASE WHEN ad.alarm_level = '0' THEN 1 ELSE 0 END) AS normalCount,
SUM(CASE WHEN ad.alarm_level = '1' THEN 1 ELSE 0 END) AS remindCount,
SUM(CASE WHEN ad.alarm_level = '2' THEN 1 ELSE 0 END) AS commonCount,
SUM(CASE WHEN ad.alarm_level = '3' THEN 1 ELSE 0 END) AS warningCount,
SUM(CASE WHEN ad.alarm_level = '4' THEN 1 ELSE 0 END) AS seriousCount
FROM alarm_detail ad
LEFT JOIN alarm_audit aa ON ad.id = aa.alarm_id
LEFT JOIN ky_category kc ON kc.code = ad.alarm_type



        AND ad.camera_id IN

            #{cameraName}




        AND kc.id IN

            #{category}




        AND ad.alarm_time BETWEEN #{startTime} AND #{endTime}



        AND aa.audit_status = #{auditStatus}



        AND aa.audit_result = #{auditResult}



        AND ad.is_rotate = #{isRotate}
